def has_mentsu(hand):
    from collections import defaultdict, Counter
    groups = defaultdict(list)
    for tile in hand:
        num = int(tile[0])
        suit = tile[1]
        groups[suit].append(num)

    for suit, numbers in groups.items():
        cnt = Counter(numbers)
        if max(cnt.values()) >= 3:
            return True

        unique_nums = sorted(set(numbers))
        n = len(unique_nums)
        for i in range(n - 2):
            if unique_nums[i+2] - unique_nums[i] == 2:
                return True
    return False

