def is_s_palindrome(s):
    # Define mirror pairs and self-mirroring characters
    mirror_pairs = {'b': 'd', 'd': 'b', 'p': 'q', 'q': 'p'}
    self_mirroring = {'o', 'x', 'O', 'X', 'H', 'I', 'M', 'T', 'U', 'V', 'v', 'w', 'W', 'Y'}

    n = len(s)

    # Check middle character for odd length strings
    if n % 2 == 1:
        mid_char = s[n // 2]
        if mid_char not in self_mirroring and mid_char not in mirror_pairs:
            return False

    # Check all character pairs
    for i in range(n // 2):
        j = n - 1 - i
        char1, char2 = s[i], s[j]

        # Check if characters are the same mirror pair or both self-mirroring
        if (char1 in mirror_pairs and mirror_pairs[char1] == char2):
            continue
        elif (char1 in self_mirroring and char2 in self_mirroring and char1 == char2):
            continue
        else:
            return False

    return True

