import math

def factorize(n):
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            count = 0
            while n % d == 0:
                count += 1
                n //= d
            factors.append((d, count))
        d += 1
    if n > 1:
        factors.append((n, 1))
    return factors

def get_divisors_and_n_factors(factors_m):
    divisors = [1]
    n_factors_list = [factors_m]  # for d=1, n = m, so factors_n = factors_m
    # We'll generate divisors by iterating over primes
    for p, exp in factors_m:
        new_divs = []
        new_n_factors = []
        for i in range(len(divisors)):
            d = divisors[i]
            n_factors = n_factors_list[i]
            # For the current prime p, we can add exponents from 0 to exp
            for e in range(1, exp+1):
                new_d = d * (p ** e)
                new_n_factor = []
                for (q, f) in n_factors:
                    if q == p:
                        new_f = f - e
                        if new_f > 0:
                            new_n_factor.append((q, new_f))
                    else:
                        new_n_factor.append((q, f))
                new_divs.append(new_d)
                new_n_factors.append(new_n_factor)
        divisors += new_divs
        n_factors_list += new_n_factors
    return divisors, n_factors_list

def totient_from_factors(factors):
    n = 1
    for p, exp in factors:
        n *= p**exp
    phi = n
    for p, exp in factors:
        phi = phi * (p-1) // p
    return phi

def multiplicative_order(a, n, phi, factors_phi):
    order = phi
    for p, exp in factors_phi:
        for i in range(exp):
            if pow(a, order // p, n) == 1:
                order //= p
            else:
                break
    return order

def main():
    data = input().split()
    if not data:
        return
    m = int(data[0])
    x = int(data[1])

    if m == 1:
        print(1)
        return

    factors_m = factorize(m)
    divisors, n_factors_list = get_divisors_and_n_factors(factors_m)

    total_cycles = 0
    for i in range(len(divisors)):
        d = divisors[i]
        if d == m:
            continue
        n_factors = n_factors_list[i]
        n = 1
        for p, exp in n_factors:
            n *= p**exp
        # Compute phi(n) from n_factors
        phi_n = totient_from_factors(n_factors)
        if n == 1:
            # Actually, n should not be 1 because d < m
            continue
        # Factorize phi_n to get factors_phi_n
        factors_phi_n = factorize(phi_n)
        a = x % n
        # Check gcd(a, n) should be 1, but it is because gcd(x, m)=1 and n|m.
        order = multiplicative_order(a, n, phi_n, factors_phi_n)
        cycles_d = phi_n // order
        total_cycles += cycles_d

    answer = 1 + total_cycles
    print(answer)

