def can_assign(x, n, a, b):
    # Recursive function to check if we can assign 4 a's and 2 b's to x bars.
    def dfs(bar_index, rem_a, rem_b):
        if bar_index == x:
            return rem_a == 0 and rem_b == 0
        # Determine the maximum number of a's we can assign to this bar without exceeding n
        max_i = min(rem_a, n // a)
        for i in range(0, max_i+1):
            # For given i, determine the maximum j such that i*a + j*b <= n
            max_j = min(rem_b, (n - i*a) // b) if b > 0 else 0
            # Also, if b==0, then we can only assign a's, but in our problem b>=1, so we don't need to worry.
            for j in range(0, max_j+1):
                if i == 0 and j == 0:
                    continue  # skip empty bar
                if dfs(bar_index+1, rem_a - i, rem_b - j):
                    return True
        return False

    return dfs(0, 4, 2)

