import math
from functools import lru_cache

def main():
    n = int(input().strip())
    a = list(map(int, input().split()))

    if n == 1:
        if a[0] > 0:
            print("BitLGM")
        else:
            print("BitAryo")
    elif n == 2:
        a0, a1 = sorted(a)
        phi = (1 + math.sqrt(5)) / 2
        k = 0
        while True:
            ak = int(k * phi)
            bk = int(k * phi * phi)
            if ak == a0 and bk == a1:
                print("BitAryo")
                return
            if ak > a0 or bk > a1:
                break
            k += 1
        print("BitLGM")
    else: # n==3
        i, j, k = a
        @lru_cache(maxsize=None)
        def win3(i, j, k):
            if i == 0 and j == 0 and k == 0:
                return False
            # Check moves on one element
            for x in range(1, i+1):
                if not win3(i-x, j, k):
                    return True
            for x in range(1, j+1):
                if not win3(i, j-x, k):
                    return True
            for x in range(1, k+1):
                if not win3(i, j, k-x):
                    return True
            # Check move on all
            min_val = min(i, j, k)
            for x in range(1, min_val+1):
                if not win3(i-x, j-x, k-x):
                    return True
            return False

        if win3(i, j, k):
            print("BitLGM")
        else:
            print("BitAryo")

