def compute_score(s, n):
    L = len(s)
    from collections import Counter
    freq = Counter(s)
    best = 0
    for ch, count in freq.items():
        moves_needed = L - count
        if n >= moves_needed:
            leftover = n - moves_needed
            if leftover % 2 == 0:
                candidate = L
            else:
                candidate = L - 1
        else:
            candidate = count + n
        if candidate > best:
            best = candidate
    return best

def main():
    n = int(input().strip())
    kuro = input().strip()
    shiro = input().strip()
    katie = input().strip()

    kuro_score = compute_score(kuro, n)
    shiro_score = compute_score(shiro, n)
    katie_score = compute_score(katie, n)

    if kuro_score > shiro_score and kuro_score > katie_score:
        print("Kuro")
    elif shiro_score > kuro_score and shiro_score > katie_score:
        print("Shiro")
    elif katie_score > kuro_score and katie_score > shiro_score:
        print("Katie")
    else:
        print("Draw")

