import math

def is_prime(x):
    if x < 2:
        return False
    if x == 2:
        return True
    if x % 2 == 0:
        return False

    # Trial division for factors up to 1000
    d = 3
    while d * d <= x and d <= 1000:
        if x % d == 0:
            return False
        d += 2
    if x <= 1000000:
        return True

    # Miller-Rabin for larger numbers
    def miller_test(a, d, s, x):
        x0 = pow(a, d, x)
        if x0 == 1 or x0 == x-1:
            return True
        for _ in range(s-1):
            x0 = (x0 * x0) % x
            if x0 == x-1:
                return True
        return False

    # Write x-1 as d * 2^s
    d = x - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1

    bases = [2, 7, 61]
    for a in bases:
        if a >= x:
            continue
        if not miller_test(a, d, s, x):
            return False
    return True

def main():
