MOD = 10**9 + 7

def main():
    import sys
    data = sys.stdin.read().split()

    n = int(data[0])
    T = int(data[1])

    songs = []
    for i in range(n):
        t = int(data[2 + 2*i])
        g = int(data[3 + 2*i])
        songs.append((t, g))

    # Precompute total duration for each mask
    total_time = [0] * (1 << n)
    for mask in range(1 << n):
        for i in range(n):
            if mask & (1 << i):
                total_time[mask] += songs[i][0]

    # dp[mask][last_genre] = count
    # last_genre: 0 = no song, 1,2,3 = actual genres
    dp = [[0] * 4 for _ in range(1 << n)]
    dp[0][0] = 1

    for mask in range(1 << n):
        for last_genre in range(4):
            if dp[mask][last_genre] == 0:
                continue
            for i in range(n):
                if mask & (1 << i):
                    continue  # song already used
                t_i, g_i = songs[i]
                if g_i != last_genre:
                    new_mask = mask | (1 << i)
                    dp[new_mask][g_i] = (dp[new_mask][g_i] + dp[mask][last_genre]) % MOD

    ans = 0
    for mask in range(1 << n):
        if total_time[mask] == T:
            for g in range(1, 4):
                ans = (ans + dp[mask][g]) % MOD

    print(ans)

if __name__ == "__main__":
    main()

