for k in range(2, 61):
    base = (1 << k) - 1
    # Calculate the smallest candidate for this k: when i = k-2
    smallest_candidate = base - (1 << (k-2))
    if smallest_candidate > b:
        break  # For larger k, candidates will be even larger, so break early.
    largest_candidate = base - 1  # when i=0
    if largest_candidate < a:
