def main():
    import sys
    data = sys.stdin.read().split()
    n = int(data[0])
    k = int(data[1])
    S = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Precompute factorial for numbers, with cap for numbers > 20
    def fact(x):
        if x > 20:
            return S + 1  # too big
        res = 1
        for i in range(1, x+1):
            res *= i
        return res

    # Split the list into two halves
    mid = n // 2
    left_list = a[:mid]
    right_list = a[mid:]

    # Generate states for the left half
    left_states = {}
    left_states[(0,0)] = 1
    for x in left_list:
        new_left = {}
        for (s, k_used), count in left_states.items():
            # Option 1: skip the cube
            new_left[(s, k_used)] = new_left.get((s, k_used), 0) + count

            # Option 2: take without factorial
            s1 = s + x
            if s1 <= S:
                new_left[(s1, k_used)] = new_left.get((s1, k_used), 0) + count

            # Option 3: take with factorial
            f_val = fact(x)
            s2 = s + f_val
            if k_used + 1 <= k and s2 <= S:
                new_left[(s2, k_used+1)] = new_left.get((s2, k_used+1), 0) + count

        left_states = new_left

    # Generate states for the right half
    right_states = {}
    right_states[(0,0)] = 1
    for x in right_list:
        new_right = {}
        for (s, k_used), count in right_states.items():
            # Option 1: skip the cube
            new_right[(s, k_used)] = new_right.get((s, k_used), 0) + count

            # Option 2: take without factorial
            s1 = s + x
            if s1 <= S:
                new_right[(s1, k_used)] = new_right.get((s1, k_used), 0) + count

            # Option 3: take with factorial
            f_val = fact(x)
            s2 = s + f_val
            if k_used + 1 <= k and s2 <= S:
                new_right[(s2, k_used+1)] = new_right.get((s2, k_used+1), 0) + count

        right_states = new_right

    # Preprocess right_states: for each sum, we want to have an array for k from 0 to k
    right_dict = {}
    for (s, k_used), count in right_states.items():
        if s not in right_dict:
            right_dict[s] = [0] * (k+1)
        if k_used <= k:
            right_dict[s][k_used] += count

    # Now iterate over left_states and combine
    ans = 0
    for (s_left, k_left), count_left in left_states.items():
        needed = S - s_left
        if needed in right_dict:
            arr = right_dict[needed]
            # We can use k_right from 0 to k - k_left
            max_k_right = k - k_left
            if max_k_right < 0:
                continue
            total_right = sum(arr[:max_k_right+1])
            ans += count_left * total_right

    print(ans)

