import math

def safe_power(base, exp, limit):
    if exp == 0:
        return 1
    result = 1
    for i in range(exp):
        result *= base
        if result > limit:
            return None
    return result

def main():
    n = int(input().strip())
    k_str = input().strip()

    if k_str == "0":
        print(0)
        return

    L = len(k_str)
    max_digit_len = len(str(n-1))

    # Initialize dp: a 2D list with dimensions (L+1) x (L+1), filled with a large number (10**18+1)
    INF = 10**18 + 1
    dp = [[INF] * (L+1) for _ in range(L+1)]
    dp[L][0] = 0  # base case: after the string, with 0 digits, value=0.

    # Iterate from the end backwards
    for i in range(L-1, -1, -1):
        for m in range(1, L-i+1):  # number of digits to use for the substring from i to end
            for j in range(i, min(i+max_digit_len, L)):
                s = k_str[i:j+1]
                # Check for leading zero: if the segment has more than one digit and starts with '0', skip.
                if len(s) > 1 and s[0] == '0':
                    continue
                d = int(s)
                if d >= n:
                    break  # since adding more digits will only make it larger, break early.
                # Check if the remainder can be represented with m-1 digits
                if j+1 <= L and m-1 >= 0 and dp[j+1][m-1] < INF:
                    # Compute n^(m-1)
                    power_val = safe_power(n, m-1, INF-1)
                    if power_val is None:
                        continue
                    total_val = d * power_val + dp[j+1][m-1]
                    if total_val < INF:
                        dp[i][m] = min(dp[i][m], total_val)

    # Find the minimal value for the entire string (i=0) over all possible m
    ans = INF
    for m in range(1, L+1):
        if dp[0][m] < ans:
            ans = dp[0][m]

    print(ans)

