    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        print(-1)
        return

    n, m = map(int, data[0].split())
    grid = []
    whites = []
    for i in range(1, 1+n):
        grid.append(data[i].strip())

    # Collect white pixels
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'w':
                whites.append((i, j))

    if not whites:
        # According to problem, at least one white, but still.
        print(-1)
        return

    # Find T, B, L, R
    T = n
    B = -1
    L = m
    R = -1
    for (i,j) in whites:
        if i < T:
            T = i
        if i > B:
            B = i
        if j < L:
            L = j
        if j > R:
            R = j

    d0 = max(B - T + 1, R - L + 1)
    found = False
    r_found = -1
    c_found = -1
    d_found = -1

    for d in range(d0, min(n, m) + 1):
        # r from max(0, B-d+1) to min(T, n-d)
        low_r = max(0, B - d + 1)
        high_r = min(T, n - d)
        if low_r > high_r:
            continue
        low_c = max(0, R - d + 1)
        high_c = min(L, m - d)
        if low_c > high_c:
            continue

        for r in range(low_r, high_r + 1):
            for c in range(low_c, high_c + 1):
                valid = True
                for (i, j) in whites:
                    if i == r or i == r+d-1:
                        if c <= j <= c+d-1:
                            continue
                    if j == c or j == c+d-1:
                        if r <= i <= r+d-1:
                            continue
                    valid = False
                    break
                if valid:
                    found = True
                    r_found = r
                    c_found = c
                    d_found = d
                    break
            if found:
                break
        if found:
            break

    if not found:
        print(-1)
    else:
        # Build output grid
        output_grid = [list(row) for row in grid]
        top = r_found
        left = c_found
        bottom = r_found + d_found - 1
        right = c_found + d_found - 1
        for j in range(left, right+1):
            if output_grid[top][j] != 'w':
                output_grid[top][j] = '+'
            if output_grid[bottom][j] != 'w':
                output_grid[bottom][j] = '+'
        for i in range(top+1, bottom):
            if output_grid[i][left] != 'w':
                output_grid[i][left] = '+'
            if output_grid[i][right] != 'w':
                output_grid[i][right] = '+'
        for i in range(n):
            print(''.join(output_grid[i]))

