import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def main():
    X = int(input().strip())
    if X == 1:
        print("1 1")
        return

    # Find divisors of X
    divisors = set()
    i = 1
    while i * i <= X:
        if X % i == 0:
            divisors.add(i)
            divisors.add(X // i)
        i += 1
    divisors = sorted(divisors)

    # Find the largest divisor d <= sqrt(X) such that gcd(d, X//d)==1
    sqrt_x = int(math.isqrt(X))
    best_d = 1
    for d in divisors:
        if d > sqrt_x:
            break
        if gcd(d, X // d) == 1:
            best_d = d

    a = best_d
    b = X // best_d
    print(f"{a} {b}")

