def count_up_to(N, k):
    if N < 0:
        return 0
    s = bin(N)[2:]
    n = len(s)
    # dp[i][tight][count] for i in [0, n]
    # Initialize: at start, we have processed 0 digits, tight=1, count=0.
    dp = [[[0] * (k+1) for _ in range(2)] for __ in range(n+1)]
    dp[0][1][0] = 1
    for i in range(n):
        for tight in range(2):
            for count in range(k+1):
                if dp[i][tight][count] == 0:
                    continue
                limit = int(s[i]) if tight else 1
                for d in range(0, limit+1):
                    new_tight = 1 if (tight and d == limit) else 0
                    new_count = count + (1 if d == 1 else 0)
                    if new_count <= k:
                        dp[i+1][new_tight][new_count] += dp[i][tight][count]
    return dp[n][0][k] + dp[n][1][k]

def main():
