        # Compute g(mid) = count_up_to(2*mid, k) - count_up_to(mid, k)
        cnt = count_up_to(2*mid, k) - count_up_to(mid, k)
        if cnt < m:
            low = mid + 1
        elif cnt > m:
            high = mid - 1
        else:
            ans = mid
            break
    print(ans)

