    if n == 1:
        print("1 0")
        return

    # Factorize n
    factors = {}
    temp = n
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
        i += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    product = 1
    exponents = []
    for prime, exp in factors.items():
        product *= prime
        exponents.append(exp)

    mx = max(exponents)
    # Find the smallest power of 2 >= mx
    k = 0
    num = 1
    while num < mx:
        num *= 2
        k += 1

    # Check if all exponents are exactly num?
    need_extra = False
    for exp in exponents:
        if exp != num:
            need_extra = True
            break

    if need_extra:
        k += 1

    print(f"{product} {k}")

