    graph = [[] for _ in range(n)]
    index = 1 + n
    for i in range(n-1):
        u = int(data[index]); v = int(data[index+1]); index += 2
        u -= 1; v -= 1
        graph[u].append(v)
        graph[v].append(u)

    M = max(a) if n > 0 else 0

    heap = []
    count = defaultdict(int)

    def insert(v):
        heapq.heappush(heap, -v)
        count[-v] += 1

    def remove(v):
        count[-v] -= 1

    def get_max():
        while heap and count[heap[0]] == 0:
            heapq.heappop(heap)
        if not heap:
            return None
        return -heap[0]

    for i in range(n):
        if a[i] == M:
            val = a[i] + 2
        else:
            val = a[i] + 1
        insert(val)

    ans = -10**18
    for i in range(n):
        # Remove node i
        if a[i] == M:
            val_i = a[i] + 2
        else:
            val_i = a[i] + 1
        remove(val_i)

        # Remove all neighbors
        for j in graph[i]:
            if a[j] == M:
                val_j = a[j] + 2
            else:
                val_j = a[j] + 1
            remove(val_j)

        candidate = a[i]
        for j in graph[i]:
            candidate = max(candidate, a[j] + 1)

        current_max = get_max()
        if current_max is not None:
            candidate = max(candidate, current_max)

        ans = max(ans, candidate)

        # Reinsert node i and its neighbors
        insert(val_i)
        for j in graph[i]:
            if a[j] == M:
                val_j = a[j] + 2
            else:
                val_j = a[j] + 1
