    data = sys.stdin.read().splitlines()
    if not data:
        print("NO")
        return

    h, w = map(int, data[0].split())
    grid = []
    for i in range(1, 1+h):
        grid.append(data[i].strip())

    candidates = []
    for i in range(1, h-1):
        for j in range(1, w-1):
            if grid[i][j] == '*':
                if grid[i-1][j] == '*' and grid[i+1][j] == '*' and grid[i][j-1] == '*' and grid[i][j+1] == '*':
                    candidates.append((i, j))

    if len(candidates) != 1:
        print("NO")
        return

    center_i, center_j = candidates[0]
    visited = set()
    visited.add((center_i, center_j))

    # Traverse up
    i = center_i - 1
    while i >= 0 and grid[i][center_j] == '*':
        visited.add((i, center_j))
        i -= 1

    # Traverse down
    i = center_i + 1
    while i < h and grid[i][center_j] == '*':
        visited.add((i, center_j))
        i += 1

    # Traverse left
    j = center_j - 1
    while j >= 0 and grid[center_i][j] == '*':
        visited.add((center_i, j))
        j -= 1

    # Traverse right
    j = center_j + 1
    while j < w and grid[center_i][j] == '*':
        visited.add((center_i, j))
        j += 1

    # Check all stars are visited
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*':
                if (i, j) not in visited:
