def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        print("NO")
        return

    n, m = map(int, data[0].split())
    grid = []
    for i in range(1, 1+n):
        grid.append(data[i].strip())

    r1, c1 = map(int, data[1+n].split())
    r2, c2 = map(int, data[2+n].split())

    # Convert to 0-indexed
    r1 -= 1; c1 -= 1
    r2 -= 1; c2 -= 1

    directions = [(0,1), (1,0), (0,-1), (-1,0)]

    # If start is the same as destination
    if (r1, c1) == (r2, c2):
        count_neighbors = 0
        for dr, dc in directions:
            nr = r2 + dr
            nc = c2 + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.':
                count_neighbors += 1
        if count_neighbors >= 1:
            print("YES")
        else:
            print("NO")
        return

    # BFS from start through '.' cells
    visited = [[False] * m for _ in range(n)]
    queue = collections.deque()
    queue.append((r1, c1))
    visited[r1][c1] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr = r + dr
            nc = c + dc
            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == '.':
                visited[nr][nc] = True
                queue.append((nr, nc))

    # Check destination
    if grid[r2][c2] == 'X':
        for dr, dc in directions:
            nr = r2 + dr
            nc = c2 + dc
            if 0 <= nr < n and 0 <= nc < m and visited[nr][nc]:
                print("YES")
                return
        print("NO")
    else:
        count_visited_neighbors = 0
        for dr, dc in directions:
            nr = r2 + dr
            nc = c2 + dc
            if 0 <= nr < n and 0 <= nc < m and visited[nr][nc]:
                count_visited_neighbors += 1
        if count_visited_neighbors >= 2:
            print("YES")
        else:
            print("NO")

