def is_leap(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    if year % 4 == 0:
        return True
    return False

def days_in_month(month, year):
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30
    else:  # February
        return 29 if is_leap(year) else 28

def date_to_days(y, m, d):
    total = 0
    # Add days for all years from 1900 to y-1
    for year in range(1900, y):
        total += 366 if is_leap(year) else 365
    # Add days for all months from January to m-1 in year y
    for month in range(1, m):
        total += days_in_month(month, y)
    # Add days from the first of the month to d (so d-1 days)
    total += d - 1
    return total

