def phi(n):
    result = n
    temp = n
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            while temp % i == 0:
                temp //= i
            result = result * (i-1) // i
        i += 1
    if temp > 1:
        result = result * (temp-1) // temp
    return result

