import itertools

def is_unimodal(arr):
    # Check if there exists an index i such that arr[0:i+1] is non-decreasing and arr[i:] is non-increasing.
    n = len(arr)
    for i in range(n):
        left = arr[:i+1]
        right = arr[i:]
        if sorted(left) == left and sorted(right, reverse=True) == right:
            return True
    return False

