import math

def lcm(a, b):
    return a * b // math.gcd(a, b)

def main():
    n = int(input().strip())
    f_list = list(map(int, input().split()))
    f = [0] * (n+1)
    for i in range(1, n+1):
        f[i] = f_list[i-1]

    dist = [-1] * (n+1)
    cycle_len = [0] * (n+1)
    visited = [False] * (n+1)

    for i in range(1, n+1):
        if not visited[i]:
            path = []
            cur = i
            while not visited[cur]:
                visited[cur] = True
                path.append(cur)
                cur = f[cur]
            if cur in path:
                idx = path.index(cur)
                L = len(path) - idx
                for j in range(idx, len(path)):
                    dist[path[j]] = 0
                    cycle_len[path[j]] = L
                for j in range(idx):
                    dist[path[j]] = idx - j
                    cycle_len[path[j]] = L
            else:
                L = cycle_len[cur]
                d = dist[cur]
                for j in range(len(path)):
                    dist[path[j]] = len(path) - j + d
                    cycle_len[path[j]] = L

    cycles_set = set()
    for i in range(1, n+1):
        if dist[i] == 0:
            cycles_set.add(cycle_len[i])

    M = 1
    for L in cycles_set:
        M = lcm(M, L)

    d_max = max(dist[1:])

    if d_max == 0:
        k = M
    else:
        k = M * ((d_max + M - 1) // M)

    print(k)

