    digits = [0, 0, 0]
    digits[0] = n % 10
    digits[1] = (n // 10) % 10
    digits[2] = n // 100
    type_set = set()
    for i in range(3):
        if digits[i] != 0:
            type_set.add(i)
    return tuple(sorted(type_set))

