    groups = {}
    for num in numbers:
        t = get_type(num)
        if t not in groups:
            groups[t] = []
        groups[t].append(num)

    non_empty_types = [t for t in groups if t != ()]
    zero_exists = (() in groups)

    n_non_empty = len(non_empty_types)
    best_size = -1
    best_mask = 0

    for bitmask in range(1 << n_non_empty):
        chosen = []
        for i in range(n_non_empty):
            if bitmask & (1 << i):
                chosen.append(non_empty_types[i])
        valid = True
        for i in range(len(chosen)):
            for j in range(i+1, len(chosen)):
                if not set(chosen[i]).isdisjoint(set(chosen[j])):
