import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    if max(a) >= k:
        print(0)
        return

    # Check for i from 1 to 100
    for i in range(1, 101):
        r = i-1
        total = 0
        for j in range(n):
            if a[j] == 0:
                continue
            N = i + n - 2 - j  # because N = r + n-1 - j
            if N < r:
                continue
            binom_val = 1
            # Compute C(N, r)
            for t in range(1, r+1):
                # Compute binom_val = binom_val * (N - r + t) // t
                binom_val = binom_val * (N - r + t) // t
                if binom_val > k:  # Avoid large numbers
                    break
            term = binom_val * a[j]
            total += term
            if total >= k:
                print(i)
                return

    # If we get here, then the positive elements are only at the end.
    b = []
    for j in range(n-1, -1, -1):
        if a[j] > 0:
            b.append(a[j])
        else:
            break

    low = 1
    high = k
    ans = high
    while low <= high:
        mid = (low + high) // 2
        r = mid - 1
        total = 0
        for t in range(len(b)):
            # Compute C(r+t, t)
            binom_val = 1
            for s in range(1, t+1):
                binom_val = binom_val * (r + s) // s
                if binom_val > k:
                    break
            total += binom_val * b[t]
            if total >= k:
                break
        if total >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    print(ans)

