from collections import deque

def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        print(0)
        return

    n, m, k = map(int, data[0].split())
    grid = [[['0'] * (k+1) for _ in range(m+1)] for __ in range(n+1)]
    index = 1
    for i in range(1, n+1):
        # skip empty line
        if index < len(data) and data[index].strip() == '':
            index += 1
        for j in range(1, m+1):
            if index >= len(data):
                break
            line = data[index].strip()
            index += 1
            for l in range(1, k+1):
                if l-1 < len(line):
                    grid[i][j][l] = line[l-1]
                else:
                    grid[i][j][l] = '0'

    # Convert to integers: 1 for working, 0 for broken.
    # Create a new grid for easier checking.
    work = [[[0] * (k+1) for _ in range(m+1)] for __ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, m+1):
            for l in range(1, k+1):
                if grid[i][j][l] == '1':
                    work[i][j][l] = 1
                else:
                    work[i][j][l] = 0

    # Directions: only positive moves
    directions = [(1,0,0), (0,1,0), (0,0,1)]

    def bfs(s_i, s_j, s_l, t_i, t_j, t_l, without=None):
        # without: (i,j,l) to avoid
        visited = [[[0] * (k+1) for _ in range(m+1)] for __ in range(n+1)]
        q = deque()
        q.append((s_i, s_j, s_l))
        visited[s_i][s_j][s_l] = 1
        while q:
            i1, j1, l1 = q.popleft()
            if (i1, j1, l1) == (t_i, t_j, t_l):
                return True
            for dx,dy,dz in directions:
                i2 = i1 + dx
                j2 = j1 + dy
                l2 = l1 + dz
                if i2 > n or j2 > m or l2 > k:
                    continue
                if without and (i2, j2, l2) == without:
                    continue
                if work[i2][j2][l2] and not visited[i2][j2][l2]:
                    visited[i2][j2][l2] = 1
                    q.append((i2, j2, l2))
        return False

    critical = 0
    for i in range(1, n+1):
        for j in range(1, m+1):
            for l in range(1, k+1):
                if work[i][j][l] == 0:
                    continue
                # Check if (i,j,l) is critical.
                found_critical = False
                # Iterate over s: <= (i,j,l)
                for s_i in range(1, i+1):
                    for s_j in range(1, j+1):
                        for s_l in range(1, l+1):
                            if work[s_i][s_j][s_l] == 0:
                                continue
                            if (s_i, s_j, s_l) == (i,j,l):
                                continue
                            # Iterate over t: >= (i,j,l)
                            for t_i in range(i, n+1):
                                for t_j in range(j, m+1):
                                    for t_l in range(l, k+1):
                                        if work[t_i][t_j][t_l] == 0:
                                            continue
                                        if (t_i, t_j, t_l) == (i,j,l):
                                            continue
                                        # Check if there is a path from s to t in the original graph (with u)
                                        if bfs(s_i, s_j, s_l, t_i, t_j, t_l):
                                            # Check without u
                                            if not bfs(s_i, s_j, s_l, t_i, t_j, t_l, without=(i,j,l)):
                                                found_critical = True
                                                break
                                    if found_critical:
                                        break
                                if found_critical:
                                    break
                            if found_critical:
                                break
                        if found_critical:
                            break
                    if found_critical:
                        break
                if found_critical:
                    critical += 1

    print(critical)

