def main():
    n = int(input().strip())
    a_list = list(map(int, input().split()))

    # If n is divisible by 7, we need to handle pens that are always on Sunday.
    # Precompute the modular inverse of n mod 7 if n % 7 != 0
    if n % 7 == 0:
        inv = None
    else:
        # Compute n^(-1) mod 7 using Fermat: n^(5) mod 7
        inv = pow(n, 5, 7)

    best_day = float('inf')
    best_pen = None

    for i in range(1, n+1):
        a_i = a_list[i-1]
        r = (i-1) % 7

        if n % 7 == 0:
            if r == 6:
                # This pen is always used on Sunday -> never runs out.
                continue
            else:
                # No Sundays for this pen
                k = a_i
                day = i + (k-1) * n
        else:
            # Compute j0: the smallest j in [0,6] such that (r + j*n) % 7 == 6
            j0 = ( (6 - r) * inv ) % 7
            # Binary search for k
            low, high = 0, a_i * 7 + 10  # safe upper bound
            while low < high:
                mid = (low + high) // 2
                # Compute number of Sundays S in first mid uses
                if mid <= j0:
                    S = 0
                else:
                    S = (mid - j0 + 6) // 7
                consumptions = mid - S
                if consumptions >= a_i:
                    high = mid
                else:
                    low = mid + 1
            k = low
            day = i + (k-1) * n

        if day < best_day:
            best_day = day
            best_pen = i

    print(best_pen)

