def solve():
    n = int(input().strip())
    l = list(map(int, input().split()))
    r = list(map(int, input().split()))

    # Check basic consistency
    if r[-1] != 0:
        print("NO")
        return

    total = [l[i] + r[i] for i in range(n)]

    # Create list of indices sorted by total in descending order
    indices = list(range(n))
    indices.sort(key=lambda i: total[i], reverse=True)

    # Assign candy values (n, n-1, n-2, ...) to children with smallest to largest total
    candies = [0] * n
    current_value = n
    candies[indices[0]] = current_value

    for i in range(1, n):
        if total[indices[i]] == total[indices[i-1]]:
            # Same total, same candy value
            candies[indices[i]] = current_value
        else:
            current_value -= 1
            candies[indices[i]] = current_value

    # Verify the solution
    for i in range(n):
        actual_l = 0
        for j in range(i):
            if candies[j] > candies[i]:
                actual_l += 1

        actual_r = 0
        for j in range(i+1, n):
            if candies[j] > candies[i]:
                actual_r += 1

        if actual_l != l[i] or actual_r != r[i]:
            print("NO")
            return

    print("YES")
    print(" ".join(map(str, candies)))

