import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        print(-1)
        return

    n = int(data[0]); m = int(data[1]); k = int(data[2])
    blocked = []
    if m > 0:
        blocked = list(map(int, data[3:3+m]))
    a_list = list(map(int, data[3+m:3+m+k]))

    # Create allowed array of size n
    allowed = [True] * n
    for s in blocked:
        if s < n:
            allowed[s] = False

    # Precompute prev array: prev[i] = largest allowed position <= i, or -1 if none.
    prev = [-1] * n
    if allowed[0]:
        prev[0] = 0
    else:
        prev[0] = -1

    for i in range(1, n):
        if allowed[i]:
            prev[i] = i
        else:
            prev[i] = prev[i-1]

    # If there is no allowed position at all, impossible.
    if prev[n-1] < 0:
        print(-1)
        return

    INF = 10**18
    ans = INF

    # Iterate over lamp powers l from 1 to k
    for l in range(1, k+1):
        steps = 0
        pos = 0
        possible = True
        while pos < n:
            # Check the segment [max(0, pos-l), pos] for an allowed position.
            idx = min(pos, n-1)
            candidate = prev[idx]
            # Check if candidate is within [pos-l, pos]
            if candidate < 0 or candidate < pos - l:
                possible = False
                break
            steps += 1
            pos = candidate + l
        if possible:
            cost = steps * a_list[l-1]
            if cost < ans:
                ans = cost

    if ans == INF:
        print(-1)
    else:
        print(ans)

