def check_add(a, b, c):
    # Simulate addition of a and b and compare with c
    i = len(a) - 1
    j = len(b) - 1
    k = len(c) - 1
    carry = 0
    while i >= 0 or j >= 0:
        d1 = int(a[i]) if i >= 0 else 0
        d2 = int(b[j]) if j >= 0 else 0
        total = d1 + d2 + carry
        carry = total // 10
        digit = total % 10
        if k < 0:
            return False
        if digit != int(c[k]):
            return False
        i -= 1
        j -= 1
        k -= 1
    if carry > 0:
        if k >= 0 and int(c[k]) == carry:
            k -= 1
        else:
            return False
    return k == -1

