def rotate_point(x, y, a, b, rotations):
    """Rotate point (x,y) around (a,b) counter-clockwise by rotations*90 degrees"""
    dx = x - a
    dy = y - b

    for _ in range(rotations):
        dx, dy = -dy, dx  # 90° counter-clockwise rotation

    return (a + dx, b + dy)

def is_square(points):
    """Check if 4 points form a square with non-zero area"""
    if len(points) != 4:
        return False

    # Calculate all pairwise distances squared
    distances = []
    for i in range(4):
        for j in range(i + 1, 4):
            x1, y1 = points[i]
            x2, y2 = points[j]
            dist_sq = (x2 - x1)**2 + (y2 - y1)**2
            distances.append(dist_sq)

    # There should be 6 distances: 4 equal sides, 2 equal diagonals
    if len(distances) != 6:
        return False

    distances.sort()

    # Check for zero area (all points coincident)
    if distances[0] == 0:
        return False

    # Check if we have exactly 4 equal sides and 2 equal diagonals
    # The 4 smallest should be sides, 2 largest should be diagonals
    sides = distances[:4]
    diagonals = distances[4:]

    # All sides should be equal
    if not all(abs(sides[0] - side) < 1e-9 for side in sides):
        return False

    # Both diagonals should be equal
    if abs(diagonals[0] - diagonals[1]) > 1e-9:
        return False

    # Diagonals should be exactly twice the side length (Pythagorean theorem)
    if abs(diagonals[0] - 2 * sides[0]) > 1e-9:
        return False

    return True

def solve_regiment(moles):
    """Find minimum moves to make 4 moles form a square"""
    min_moves = float('inf')
    found = False

    # Precompute all possible rotated positions for each mole
    rotated_positions = []
    for mole in moles:
        x, y, a, b = mole
        positions = []
        for rotations in range(4):
            positions.append(rotate_point(x, y, a, b, rotations))
        rotated_positions.append(positions)

    # Try all combinations of rotations
    for i in range(4):
        for j in range(4):
            for k in range(4):
                for l in range(4):
                    points = [
                        rotated_positions[0][i],
                        rotated_positions[1][j],
                        rotated_positions[2][k],
                        rotated_positions[3][l]
                    ]

                    if is_square(points):
                        total_moves = i + j + k + l
                        min_moves = min(min_moves, total_moves)
                        found = True

    return min_moves if found else -1

