def parse_price(price_str):
    parts = price_str.split('.')
    if len(parts) == 1:
        dollars = int(parts[0])
        cents = 0
    else:
        last = parts[-1]
        if len(last) == 2:
            # This is cents
            dollars_str = ''.join(parts[:-1])
            cents = int(last)
            dollars = int(dollars_str) if dollars_str != '' else 0
        else:
            # All parts are thousand groups
            dollars_str = ''.join(parts)
            dollars = int(dollars_str)
            cents = 0
    return dollars * 100 + cents

def format_total(total_cents):
    dollars = total_cents // 100
    cents = total_cents % 100
    if dollars == 0:
        dollars_str = "0"
    else:
        s = str(dollars)
        n = len(s)
        groups = []
        i = n
        while i > 0:
            start = max(0, i-3)
            groups.append(s[start:i])
            i -= 3
        dollars_str = '.'.join(reversed(groups))
    if cents > 0:
        return dollars_str + '.' + str(cents).zfill(2)
    else:
        return dollars_str

