        e = int(data[index+1])
        index += 2
        opponents.append((p, e))

    min_effort = float('inf')
    total_combinations = 1 << n

    for mask in range(total_combinations):
        wins = 0
        effort = 0
        opponent_final_points = []

        # Determine wins/losses and calculate effort
        for i in range(n):
            if mask & (1 << i):
                wins += 1
                effort += opponents[i][1]
                opponent_final_points.append(opponents[i][0])  # opponent doesn't get extra point if Manao wins
            else:
                opponent_final_points.append(opponents[i][0] + 1)  # opponent gets +1 if Manao loses

        manao_points = wins
        better_than_manao = 0

        # Count opponents who rank better than Manao
        for points in opponent_final_points:
            if points > manao_points:
                better_than_manao += 1
            elif points == manao_points:
                # Check if this opponent beat Manao (i.e., Manao lost to them)
                # We need to find which opponents have exactly manao_points and Manao lost to them
                pass

        # Now we need to carefully handle opponents with same points
        # Let's reconstruct which opponents beat Manao (have same points and Manao lost to them)
        better_than_manao = 0
