    s = seq[:]  # make a copy
    n = len(s)
    while True:
        s.sort(reverse=True)
        if s[0] == 0:
            return True
        d = s[0]
        if d < 0:
            return False
        if d >= n:
            return False
        s[0] = 0
        for i in range(1, d+1):
            s[i] -= 1
            if s[i] < 0:
                return False

