from collections import deque

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it)); m = int(next(it)); T_val = int(next(it))
    graph = [[] for _ in range(n+1)]
    in_degree = [0] * (n+1)
    for i in range(m):
        u = int(next(it)); v = int(next(it)); t = int(next(it))
        graph[u].append( (v, t) )
        in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    topo_order = []
    q = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            q.append(i)

    while q:
        u = q.popleft()
        topo_order.append(u)
        for (v, w) in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Initialize states: for each node, a list of (count, time, prev_node)
    states = [[] for _ in range(n+1)]
    states[1] = [(1, 0, -1)]   # at node1, count=1, time=0, no previous

    # Function to insert a state into a node's list while maintaining non-dominance
    def insert_state(lst, new_state):
        c, t, prev = new_state
        # Binary search to find insertion position
        low, high = 0, len(lst)-1
        pos = len(lst)
        while low <= high:
            mid = (low+high)//2
            if lst[mid][0] < c:
                low = mid+1
            else:
                high = mid-1
                pos = mid

        # Check if new state is dominated by the state at pos-1 (if exists)
        if pos > 0 and lst[pos-1][1] <= t:
            return   # dominated

        # Check if new state is dominated by the state at pos (if exists and same count)
        if pos < len(lst) and lst[pos][0] == c:
            if t < lst[pos][1]:
                # replace
                lst[pos] = (c, t, prev)
            else:
                return
            # Now check if it dominates others
        else:
            lst.insert(pos, (c, t, prev))

        # Now remove states that are dominated by the new state (to the right)
        i = pos+1
        while i < len(lst):
            if lst[i][1] >= t:
                del lst[i]
            else:
                i += 1

    # Process nodes in topological order
    for u in topo_order:
        for state in states[u]:
            c, t, prev = state
            for (v, w) in graph[u]:
                new_t = t + w
                if new_t <= T_val:
                    new_c = c + 1
                    new_state = (new_c, new_t, u)
                    insert_state(states[v], new_state)

    # Find the state with maximum count in states[n]
    best_count = -1
    best_state = None
    for state in states[n]:
        if state[0] > best_count:
            best_count = state[0]
            best_state = state

    # Reconstruct the path
    path = []
    current_node = n
    current_count = best_count
    while current_node != -1:
        path.append(current_node)
        # Find the state in states[current_node] with count = current_count
        found = None
        for state in states[current_node]:
            if state[0] == current_count:
                found = state
                break
        if found is None:
            break
        prev_node = found[2]
        current_node = prev_node
        current_count -= 1

    path.reverse()

    # Output
    print(len(path))
    print(" ".join(map(str, path)))

