def simulate_destruction(arr):
    while True:
        n_arr = len(arr)
        if n_arr == 0:
            break
        groups = []
        i = 0
        while i < n_arr:
            j = i
            while j < n_arr and arr[j][0] == arr[i][0]:
                j += 1
            groups.append((i, j-1))
            i = j

        found = False
        for (start, end) in groups:
            length = end - start + 1
            if length >= 3:
                arr = arr[:start] + arr[end+1:]
                found = True
                break
        if not found:
            break
    return arr

