def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    T = int(data[1])
    t = list(map(int, data[2:2+n]))

    max_n = n
    fact = [1] * (max_n+1)
    inv_fact = [1] * (max_n+1)

    for i in range(1, max_n+1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    power2 = [1] * (max_n+1)
    inv2 = pow(2, MOD-2, MOD)
    for i in range(1, max_n+1):
        power2[i] = power2[i-1] * inv2 % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

    prefix = 0
    E = 0
    for i in range(1, n+1):
        prefix += t[i-1]
        if prefix > T:
            break
        if prefix + i <= T:
            E = (E + 1) % MOD
        else:
            k_max = T - prefix
            if k_max < 0:
                continue
            total = 0
            for k in range(0, k_max+1):
                total = (total + nCr(i, k)) % MOD
            pr = total * power2[i] % MOD
            E = (E + pr) % MOD

    print(E % MOD)

