    in_stack = [[False] * m for _ in range(n)]
    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    def dfs(i, j):
        if in_stack[i][j]:
            return float('inf')
        if dp[i][j] != -1:
            return dp[i][j]

        in_stack[i][j] = True
        c = grid[i][j]
        if c == 'D':
            next_char = 'I'
        elif c == 'I':
