        else:
            in_stack[i][j] = False
            dp[i][j] = 0
            return 0

        best = -10**9
        for dx,dy in directions:
            ni = i + dx
            nj = j + dy
            if ni < 0 or ni >= n or nj < 0 or nj >= m:
                continue
            if grid[ni][nj] == next_char:
                res = dfs(ni, nj)
                if res == float('inf'):
                    in_stack[i][j] = False
                    return float('inf')
                if res > best:
                    best = res

        in_stack[i][j] = False
        if best == -10**9:
            if c == 'A':
                dp[i][j] = 1
            else:
                dp[i][j] = 0
        else:
