def main():
    s = input().strip()
    m = int(input().strip())
    available = []
    for i in range(1, 11):
        if s[i-1] == '1':
            available.append(i)

    # DP: we will create a list of dictionaries for each step.
    # Each state is (diff, last_weight), and we store the previous state and the weight used to get here.
    # We cap the diff to [-1000, 1000] to avoid state explosion.
    MAX_DIFF = 1000
    # Initialize dp[0] = { (0,0): None }
    dp = [dict() for _ in range(m+1)]
    dp[0][(0,0)] = None   # at step0, diff=0, last=0, no predecessor.

    # Predefine the transitions
    for i in range(m):
        for state, _ in list(dp[i].items()):
            diff, last = state
            for w in available:
                if w == last:
                    continue
                if i % 2 == 0:  # left pan
                    new_diff = diff + w
                    if new_diff > 0 and abs(new_diff) <= MAX_DIFF:
                        new_state = (new_diff, w)
                        if new_state not in dp[i+1]:
                            dp[i+1][new_state] = (diff, last, w)   # store the previous state and the weight used
                else:            # right pan
                    new_diff = diff - w
                    if new_diff < 0 and abs(new_diff) <= MAX_DIFF:
                        new_state = (new_diff, w)
                        if new_state not in dp[i+1]:
                            dp[i+1][new_state] = (diff, last, w)

    if not dp[m]:
        print("NO")
    else:
        # Backtrack to find the sequence
        path = []
        # Pick any state in dp[m]
        state = next(iter(dp[m].keys()))
        current_diff, current_last = state
        for i in range(m, 0, -1):
            # Get the predecessor info from dp[i][state]
            prev_diff, prev_last, w = dp[i][(current_diff, current_last)]
            path.append(w)
            current_diff, current_last = prev_diff, prev_last
        path.reverse()
        print("YES")
        print(" ".join(map(str, path)))

