    it = iter(data)
    n = int(next(it)); m = int(next(it)); k = int(next(it))
    c = [int(next(it)) for _ in range(k)]
    edges = []
    for i in range(m):
        u = int(next(it)); v = int(next(it)); x = int(next(it))
        edges.append((u, v, x))

    # Precompute type for each bacteria
    type_of = [0] * (n+1)
    total = 0
    for i in range(k):
        for j in range(total+1, total + c[i] + 1):
            type_of[j] = i
        total += c[i]

    # Initialize DSU for zero edges
    dsu = DSU(n)
    for (u, v, x) in edges:
        if x == 0:
            dsu.union(u, v)

    # Check each type for zero-cost connectivity
    start_index = 1
    for i in range(k):
        if c[i] == 0:
            continue
        root = dsu.find(start_index)
        for j in range(start_index+1, start_index + c[i]):
            if dsu.find(j) != root:
                print("No")
                return
        start_index += c[i]

    # Now build the type graph
    INF = 10**9
    D = [[INF] * k for _ in range(k)]
    for i in range(k):
        D[i][i] = 0

    for (u, v, x) in edges:
        i1 = type_of[u]
        i2 = type_of[v]
        if i1 != i2:
            if x < D[i1][i2]:
                D[i1][i2] = x
                D[i2][i1] = x

    # Floyd-Warshall
    for mid in range(k):
        for i in range(k):
            if D[i][mid] == INF:
                continue
            for j in range(k):
                if D[i][mid] + D[mid][j] < D[i][j]:
                    D[i][j] = D[i][mid] + D[mid][j]

    # Replace INF with -1
    for i in range(k):
        for j in range(k):
            if D[i][j] == INF:
                D[i][j] = -1

    # Output
    print("Yes")
    for i in range(k):
        print(" ".join(str(x) for x in D[i]))

