MOD = 998244353

def solve_chain(chain, k):
    L = len(chain)
    # dp[i][c] for i in range(L), c in range(1, k+1)
    # We will use 1-indexed colors: colors from 1 to k.
    dp = [[0] * (k+1) for _ in range(L)]

    # Initialize the first element
    if chain[0] == -1:
        for c in range(1, k+1):
            dp[0][c] = 1
    else:
        c0 = chain[0]
        dp[0][c0] = 1

    for i in range(1, L):
        total_prev = sum(dp[i-1]) % MOD
        if chain[i] == -1:
            for c in range(1, k+1):
                # number of ways for i-1 that are not c
                ways = (total_prev - dp[i-1][c]) % MOD
                dp[i][c] = ways
        else:
            c0 = chain[i]
            ways = (total_prev - dp[i-1][c0]) % MOD
            dp[i][c0] = ways

    return sum(dp[L-1]) % MOD

