class StringState:
    def __init__(self, s):
        self.s = s
        self.n = len(s)
        self.first = s[0]
        self.last = s[-1]
        self.max_beauty = self.calc_max_beauty(s)
        self.prefix = {}
        self.suffix = {}
        for c in 'abcdefghijklmnopqrstuvwxyz':
            self.prefix[c] = self.get_prefix(s, c)
            self.suffix[c] = self.get_suffix(s, c)

    def calc_max_beauty(self, s):
        max_run = 0
        current_run = 0
        prev = None
        for char in s:
            if char == prev:
                current_run += 1
            else:
                current_run = 1
                prev = char
            if current_run > max_run:
                max_run = current_run
        return max_run

    def get_prefix(self, s, c):
        count = 0
        for char in s:
            if char == c:
                count += 1
            else:
                break
        return count

    def get_suffix(self, s, c):
        count = 0
        for char in reversed(s):
            if char == c:
                count += 1
            else:
                break
        return count

