def multiply(S, t):
    # Create a new state for S * t
    t_len = len(t)
    t_state = StringState(t)

    # New length: (S.n + 1) * t_len + S.n
    # But we cap at 10**9 if needed?
    new_n = (S.n + 1) * t_len + S.n
    if new_n > 10**9:
        new_n = 10**9

    new_first = t[0]
    new_last = t[-1]

    new_max_beauty = max(S.max_beauty, t_state.max_beauty)

    new_prefix = {}
    new_suffix = {}

    for c in 'abcdefghijklmnopqrstuvwxyz':
        pre_t = t_state.prefix[c]
        suf_t = t_state.suffix[c]
        full_t = (pre_t == t_len)

        # Compute new prefix for c
        if pre_t < t_len:
            new_pre = pre_t
        else:
            # t is all c
            new_pre = t_len + S.prefix[c] * (1 + t_len)
            if new_pre > 10**9:
                new_pre = 10**9
        new_prefix[c] = new_pre

        # Compute new suffix for c
        if suf_t < t_len:
            new_suf = suf_t
        else:
            # t is all c
            new_suf = t_len + S.suffix[c] * (1 + t_len)
            if new_suf > 10**9:
                new_suf = 10**9
        new_suffix[c] = new_suf

        # Now, update new_max_beauty using c
        if S.prefix[c] == S.n: # S is all c
            if full_t:
                candidate = (S.n + 1) * t_len + S.n
            else:
                candidate = suf_t + 1 + pre_t
        else:
            candidate = suf_t + 1 + pre_t
        if candidate > new_max_beauty:
            new_max_beauty = candidate

        # Also, if there is a run in the middle
        if S.suffix[c] > 0 and pre_t > 0:
            candidate = S.suffix[c] + pre_t + 1
            if candidate > new_max_beauty:
                new_max_beauty = candidate
        if S.prefix[c] > 0 and suf_t > 0:
            candidate = S.prefix[c] + suf_t + 1
            if candidate > new_max_beauty:
                new_max_beauty = candidate

    # Create a new state without storing the string
    new_state = StringState("")  # we won't use the string
    new_state.n = new_n
    new_state.first = new_first
    new_state.last = new_last
    new_state.max_beauty = new_max_beauty
    new_state.prefix = new_prefix
    new_state.suffix = new_suffix
    return new_state

