import heapq

def main():
    import sys
    data = sys.stdin.read().split()
    n = int(data[0])
    k = int(data[1])
    x = int(data[2])
    arr = list(map(int, data[3:3+n]))

    neg_count = 0
    for num in arr:
        if num < 0:
            neg_count += 1

    # Create a min-heap: (absolute value, index)
    heap = []
    for i, num in enumerate(arr):
        heapq.heappush(heap, (abs(num), i))

    for _ in range(k):
        abs_val, idx = heapq.heappop(heap)
        current_val = arr[idx]
        # Check the current sign of the product
        if neg_count % 2 == 1:  # product is negative -> make abs larger
            if current_val < 0:
                arr[idx] -= x
            else:
                arr[idx] += x
        else:  # product positive -> make abs smaller (towards zero)
            if current_val < 0:
                arr[idx] += x
            else:
                arr[idx] -= x

        # Check if the sign changed
        old_sign = (current_val < 0)
        new_sign = (arr[idx] < 0)
        if old_sign != new_sign:
            if old_sign:
                neg_count -= 1
            else:
                neg_count += 1

        # Push the updated absolute value
        heapq.heappush(heap, (abs(arr[idx]), idx))

    print(" ".join(map(str, arr)))

