import math
from collections import deque, defaultdict

MAX = 1000000

def precompute_spf(n):
    spf = list(range(n+1))
    for i in range(2, int(math.isqrt(n)) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i*i, n+1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def factorize(x, spf):
    factors = []
    while x > 1:
        p = spf[x]
        count = 0
        while x % p == 0:
            count += 1
            x //= p
        if count % 2 == 1:
            factors.append(p)
    return factors

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    spf = precompute_spf(MAX)

    simplified_list = []
    for num in a:
        factors = factorize(num, spf)
        s = 1
        for p in factors:
            s *= p
        simplified_list.append(s)

    # Check for 1
    for s in simplified_list:
        if s == 1:
            print(1)
            return

    # Check for duplicates
    from collections import Counter
    count_s = Counter(simplified_list)
    for s, cnt in count_s.items():
        if cnt >= 2:
            print(2)
            return

    # Build graph
    graph = defaultdict(list)
    nodes_set = set()
    for s in simplified_list:
        factors = factorize(s, spf)  # This will return the primes in s
        if len(factors) == 0:
            # s=1, but we already handled
            continue
        elif len(factors) == 1:
            p = factors[0]
            nodes_set.add(p)
            nodes_set.add(1)
            graph[p].append(1)
            graph[1].append(p)
        else:
            p, q = factors
            nodes_set.add(p)
            nodes_set.add(q)
            graph[p].append(q)
            graph[q].append(p)

    nodes = sorted(nodes_set)   # To avoid changing during iteration
    # Remove duplicate edges in graph? Actually, we don't need to because we already have distinct simplified values.
    # But we can make sure each neighbor list is unique.
    for node in graph:
        graph[node] = list(set(graph[node]))

    # Now find shortest cycle using BFS from each node with depth limit.
    ans = float('inf')
    # We'll limit BFS to depth 5 since the cycle we want is small.
    for node in nodes:
        dist = {}
        parent = {}
        queue = deque()
        queue.append(node)
        dist[node] = 0
        parent[node] = -1
        while queue:
            u = queue.popleft()
            if dist[u] > 5:  # depth limit
                break
            for v in graph[u]:
                if v == parent[u]:
                    continue
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < ans:
                        ans = cycle_len
    if ans == float('inf'):
        print(-1)
    else:
        print(ans)

