class SegmentTree:
    def __init__(self, n, initial_arr):
        self.n = n
        self.a = initial_arr
        self.lazy = [None] * (4 * n)

    def query(self, idx, l=1, r=None, i=1):
        if r is None:
            r = self.n
        # Check lazy value
        if self.lazy[i] is not None:
            if l != r:
                self.lazy[2*i] = self.lazy[i]
                self.lazy[2*i+1] = self.lazy[i]
            self.lazy[i] = None
        if l == r:
            if self.lazy[i] is not None:
                return self.lazy[i]
            else:
                return self.a[l-1]
        mid = (l + r) // 2
        if idx <= mid:
            return self.query(idx, l, mid, 2*i)
        else:
            return self.query(idx, mid+1, r, 2*i+1)

    def update(self, ul, ur, v, l=1, r=None, i=1):
        if r is None:
            r = self.n
        if self.lazy[i] is not None:
            if l != r:
                self.lazy[2*i] = self.lazy[i]
                self.lazy[2*i+1] = self.lazy[i]
            self.lazy[i] = None
        if ul > r or ur < l:
            return
        if ul <= l and r <= ur:
            self.lazy[i] = v
            return
        mid = (l + r) // 2
        self.update(ul, ur, v, l, mid, 2*i)
        self.update(ul, ur, v, mid+1, r, 2*i+1)

