class Expression:
    pass

class VariableExpression(Expression):
    def __init__(self, name):
        self.name = name
    def __hash__(self):
        return hash(('var', self.name))
    def __eq__(self, other):
        return isinstance(other, VariableExpression) and self.name == other.name
    def __repr__(self):
        return self.name

class OpExpression(Expression):
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right
    def __hash__(self):
        return hash(('op', self.op, self.left, self.right))
    def __eq__(self, other):
        return isinstance(other, OpExpression) and self.op == other.op and self.left == other.left and self.right == other.right
    def __repr__(self):
        return f"({self.left} {self.op} {self.right})"

def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0])
    program = data[1:1+n]

    var_to_expr = {}
    expr_to_var = {}

    for line in program:
        parts = line.split('=')
        lvalue = parts[0]
        rhs = parts[1]

        if len(rhs) == 1 or (len(rhs) > 1 and rhs[1] not in ['$','^','#','&']):
            # Direct assignment: rhs is a variable
            if rhs in var_to_expr:
                expr = var_to_expr[rhs]
            else:
                expr = VariableExpression(rhs)
        else:
            # Binary operation
            # Find the operation character
            op_char = None
            for op in ['$','^','#','&']:
                if op in rhs:
                    op_char = op
                    break
            if op_char is None:
                # Should not happen
                expr = VariableExpression(rhs)
            else:
                idx = rhs.index(op_char)
                arg1 = rhs[:idx]
                arg2 = rhs[idx+1:]
                left_expr = var_to_expr[arg1] if arg1 in var_to_expr else VariableExpression(arg1)
                right_expr = var_to_expr[arg2] if arg2 in var_to_expr else VariableExpression(arg2)
                expr = OpExpression(op_char, left_expr, right_expr)

        # Check if we have seen this expression before
        if expr in expr_to_var:
            var_to_expr[lvalue] = expr_to_var[expr]
        else:
            var_to_expr[lvalue] = expr
            expr_to_var[expr] = lvalue

    if 'res' not in var_to_expr:
        print(0)
        return

    # Collect all expressions needed for 'res'
    root_expr = var_to_expr['res']
    needed_exprs = set()
    stack = [root_expr]
    while stack:
        e = stack.pop()
        if isinstance(e, OpExpression):
            needed_exprs.add(e)
            stack.append(e.left)
            stack.append(e.right)

    # Now, we need to output the expressions in the order they first appeared.
    # We iterate over the original program lines to find the first occurrence of each needed expression.
    output_lines = []
    # We will also need a function to get the representative variable for an expression.
    def get_rep(e):
        if isinstance(e, VariableExpression):
            return e.name
        else:
            return expr_to_var[e]

    # We need to avoid outputting the same expression multiple times.
    emitted = set()
    for line in program:
        parts = line.split('=')
        lvalue = parts[0]
        rhs = parts[1]
        # Check if this line assigned an expression that is needed and whose representative is lvalue.
        if lvalue in var_to_expr:
            expr = var_to_expr[lvalue]
            if expr in expr_to_var and expr_to_var[expr] == lvalue and expr in needed_exprs and expr not in emitted:
                # This line is the first occurrence of this expression.
                if isinstance(expr, OpExpression):
                    left_rep = get_rep(expr.left)
                    right_rep = get_rep(expr.right)
                    new_rhs = left_rep + expr.op + right_rep
                    output_lines.append(lvalue + '=' + new_rhs)
                else:
                    # Should not happen for op expressions, but for direct assignment of a variable?
                    # Actually, if it is a leaf, we don't output.
                    pass
                emitted.add(expr)

    # Also, we need to output the assignment for res?
    # But res might be an alias. So we output the expression for res separately?
    # Actually, we have already collected the expressions for res. But we need to output the line for res?
    # However, the value of res is computed from the expressions we output. So we need to output a line for res?
    # But wait: in the example, they output "res=aaaa^aaaa".
    # So we need to output the assignment to res.
    # But note: the expression for res might be an alias. So we generate:
    res_expr = var_to_expr['res']
    if isinstance(res_expr, VariableExpression):
        # Then res is an alias to a variable. So we don't need to output a line for res? But actually, we must output the assignment to res.
        # However, if it is an alias, we can output "res = rep"
        rep = get_rep(res_expr)
        if rep != 'res':
            output_lines.append('res=' + rep)
    else:
        # It is an op expression, and we have already output the expression itself? But wait, if the expression for res is needed, we have output it in the loop above?
        # But then we need to assign res to the representative of that expression?
        # Actually, no: because the expression for res is stored in its representative variable. So we output "res = rep(res_expr)"
        rep = get_rep(res_expr)
        if rep != 'res':
            output_lines.append('res=' + rep)

    # However, we must be cautious: if the representative for res_expr is 'res', then we don't need to output.
    # So we output the number of lines and then the lines.
    print(len(output_lines))
    for line in output_lines:
        print(line)

