import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a_list = list(map(int, data[1:1+n-1]))

    # Create array a of length n+1 (1-indexed)
    a = [0] * (n+1)
    for i in range(1, n):
        a[i] = a_list[i-1]
    a[n] = n  # for station n, set to n

    # Build segment tree for range maximum query (value, index) with tie broken by larger index.
    size = n
    tree = [None] * (4 * size)

    def combine(left, right):
        if left is None:
            return right
        if right is None:
            return left
        if left[0] > right[0]:
            return left
        elif left[0] < right[0]:
            return right
        else:
            if left[1] > right[1]:
                return left
            else:
                return right

    def build(idx, l, r):
        if l == r:
            tree[idx] = (a[l], l)
        else:
            mid = (l + r) // 2
            build(2*idx, l, mid)
            build(2*idx+1, mid+1, r)
            tree[idx] = combine(tree[2*idx], tree[2*idx+1])

    def query(idx, l, r, ql, qr):
        if ql > r or qr < l:
            return None
        if ql <= l and r <= qr:
            return tree[idx]
        mid = (l + r) // 2
        left_res = None
        right_res = None
        if ql <= mid:
            left_res = query(2*idx, l, mid, ql, qr)
        if qr > mid:
            right_res = query(2*idx+1, mid+1, r, ql, qr)
        return combine(left_res, right_res)

    # Build segment tree for indices 1 to n
    build(1, 1, n)

    dp = [0] * (n+1)
    ans = 0
    # Iterate from n-1 down to 1
    for i in range(n-1, 0, -1):
        # Query range [i+1, a[i]]
        res = query(1, 1, n, i+1, a[i])
        j = res[1]
        dp[i] = dp[j] + (n - i) - (a[i] - j)
        ans += dp[i]

    print(ans)

