    LOG = 18
    dp = [[0] * (MAX_COORD+1) for _ in range(LOG)]

    # Initialize dp[0]
    for i in range(0, MAX_COORD+1):
        if best[i] <= i:
            dp[0][i] = i
        else:
            dp[0][i] = best[i]

    # Build the sparse table
    for j in range(1, LOG):
        for i in range(0, MAX_COORD+1):
            dp[j][i] = dp[j-1][ dp[j-1][i] ]

