import math

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        self.tree = [0] * (2 * self.size)
        self.build(data)

    def build(self, data):
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        for i in range(self.n, self.size):
            self.tree[self.size + i] = 0
        for i in range(self.size-1, 0, -1):
            self.tree[i] = math.gcd(self.tree[2*i], self.tree[2*i+1])

    def query(self, l, r):
        # query [l, r] inclusive
        l += self.size
        r += self.size
        res = 0
        while l <= r:
            if l % 2 == 1:
                res = math.gcd(res, self.tree[l])
                l += 1
            if r % 2 == 0:
                res = math.gcd(res, self.tree[r])
                r -= 1
            l //= 2
            r //= 2
        return res

