def is_complete_binary_tree(adj, n):
    # Find root (vertex with degree 2)
    roots = []
    for i in range(1, len(adj)):
        if adj[i] and len(adj[i]) == 2:
            roots.append(i)

    if len(roots) != 1:
        return False

    root = roots[0]
    visited = set()
    depth_map = {}

    def dfs(node, parent, depth):
        visited.add(node)
        depth_map[node] = depth
        children = [neighbor for neighbor in adj[node] if neighbor != parent]

        if depth < n - 1:  # Should have exactly 2 children
            if len(children) != 2:
                return False
        else:  # Leaf level, should have no children
            if len(children) != 0:
                return False

        for child in children:
            if not dfs(child, node, depth + 1):
                return False
        return True

    if not dfs(root, -1, 0):
        return False

    # Check if all leaves are at the same depth
    leaf_depths = [depth for node, depth in depth_map.items() 
                  if len(adj[node]) == 1 and node != root]
    if leaf_depths and len(set(leaf_depths)) != 1:
        return False

    return len(visited) == (2**n - 1)

