import math

def is_prime(x):
    if x < 2:
        return False
    if x == 2:
        return True
    if x % 2 == 0:
        return False
    sqrt_x = int(math.isqrt(x))
    for i in range(3, sqrt_x+1, 2):
        if x % i == 0:
            return False
    return True

def get_smallest_prime_factor(x):
    if x % 2 == 0:
        return 2
    sqrt_x = int(math.isqrt(x))
    for i in range(3, sqrt_x+1, 2):
        if x % i == 0:
            return i
    return x  # which is prime, but we already checked that x is composite in the caller

def main():
    n = int(input().strip())
    if n == 1:
        print("No")
        return

    total_sum = n * (n+1) // 2
    if is_prime(total_sum):
        print("No")
        return

    # Find the smallest prime divisor of total_sum
    d = get_smallest_prime_factor(total_sum)

    # Group numbers 1..n by residue modulo d
    groups = [[] for _ in range(d)]
    for i in range(1, n+1):
        r = i % d
        groups[r].append(i)

    S2 = []
    if groups[0]:
        # Take one element from residue0
        S2 = [groups[0][0]]
    else:
        # Find a pair (r, d-r)
        for r in range(1, d):
            if groups[r] and groups[d - r]:
                S2 = [groups[r][0], groups[d - r][0]]
                break

    # Now, S1 is all numbers not in S2
    S1 = []
    for i in range(1, n+1):
        if i not in S2:
            S1.append(i)

    # Output
    print("Yes")
    # Print S1
    print(str(len(S1)) + " " + " ".join(map(str, S1)))
    print(str(len(S2)) + " " + " ".join(map(str, S2)))

