class AhoNode:
    __slots__ = ['goto', 'fail', 'output']

    def __init__(self):
        self.goto = {}
        self.fail = None
        self.output = []

def build_automaton(patterns):
    root = AhoNode()

    # Build trie
    for i, pattern in enumerate(patterns):
        node = root
        for char in pattern:
            if char not in node.goto:
                node.goto[char] = AhoNode()
            node = node.goto[char]
        node.output.append(i)

    # Build failure links using BFS
    queue = []
    for char, child in root.goto.items():
        child.fail = root
        queue.append(child)

    while queue:
        node = queue.pop(0)
        for char, child in node.goto.items():
            queue.append(child)
            fail_node = node.fail
            while fail_node is not None and char not in fail_node.goto:
                fail_node = fail_node.fail
            child.fail = fail_node.goto[char] if fail_node else root
            child.output.extend(child.fail.output)

    return root

def main():
    t = input().strip()
    n = int(input())
    patterns = []
    for _ in range(n):
        patterns.append(input().strip())

    if not patterns:
        print(0)
        return

    # Build Aho-Corasick automaton
    root = build_automaton(patterns)

    # Process text to find pattern endings
    ends = [0] * (len(t) + 2)  # ends[i] = count of patterns ending at position i
    node = root
    for i, char in enumerate(t):
        while node is not None and char not in node.goto:
            node = node.fail
        if node is None:
            node = root
            continue
        node = node.goto[char]
        for pattern_idx in node.output:
            ends[i + 1] += 1  # pattern ends at position i+1

    # Get pattern lengths to find starting positions
    pattern_lens = [len(p) for p in patterns]
    starts = [0] * (len(t) + 2)  # starts[i] = count of patterns starting at position i

    # Reset and process again to find pattern starts
    node = root
    for i, char in enumerate(t):
        while node is not None and char not in node.goto:
            node = node.fail
        if node is None:
            node = root
            continue
        node = node.goto[char]
        for pattern_idx in node.output:
            start_pos = i - pattern_lens[pattern_idx] + 2
            if start_pos >= 1:
                starts[start_pos] += 1

    # Calculate the answer
    ans = 0
    for k in range(1, len(t) + 1):
        if k + 1 <= len(t):
            ans += ends[k] * starts[k + 1]

    print(ans)

