INF = 10**9

class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size *= 2
        self.data = [INF] * (2 * self.size)

    def update(self, index, value):
        i = index - 1 + self.size
        if value < self.data[i]:
            self.data[i] = value
            while i > 1:
                i //= 2
                self.data[i] = min(self.data[2*i], self.data[2*i+1])

    def query(self, l, r):
        l0 = l - 1 + self.size
        r0 = r - 1 + self.size
        res = INF
        while l0 <= r0:
            if l0 % 2 == 1:
                res = min(res, self.data[l0])
                l0 += 1
            if r0 % 2 == 0:
                res = min(res, self.data[r0])
                r0 -= 1
            l0 //= 2
            r0 //= 2
        return res

