import sys

class Fenw:
    def __init__(self, size):
        self.n = size
        self.data_max = [0] * (self.n + 1)
        self.data_cnt = [0] * (self.n + 1)

    def update(self, index, value, count):
        i = index
        while i <= self.n:
            if self.data_max[i] < value:
                self.data_max[i] = value
                self.data_cnt[i] = count
            elif self.data_max[i] == value:
                self.data_cnt[i] += count
            i += i & -i

    def query(self, index):
        res_max = 0
        res_cnt = 0
        i = index
        while i > 0:
            if self.data_max[i] > res_max:
                res_max = self.data_max[i]
                res_cnt = self.data_cnt[i]
            elif self.data_max[i] == res_max:
                res_cnt += self.data_cnt[i]
            i -= i & -i
        return (res_max, res_cnt)

def compress(arr):
    sorted_vals = sorted(set(arr))
    mapping = {}
    for idx, val in enumerate(sorted_vals, start=1):
        mapping[val] = idx
    compressed_arr = [mapping[x] for x in arr]
    return compressed_arr, mapping, len(sorted_vals)

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Compress the original array and also the negated array for backward pass
    all_vals = set()
    for x in a:
        all_vals.add(x)
        all_vals.add(-x)
    sorted_vals = sorted(all_vals)
    mapping = {}
    for idx, val in enumerate(sorted_vals, start=1):
        mapping[val] = idx
    comp_size = len(sorted_vals)

    # Forward pass
    f_len = [0] * n
    f_cnt = [0] * n
    fenw_forward = Fenw(comp_size)
    for i in range(n):
        val = a[i]
        comp_val = mapping[val]
        # Query for [1, comp_val-1]
        if comp_val > 1:
            max_len, cnt = fenw_forward.query(comp_val-1)
        else:
            max_len, cnt = (0,0)
        if max_len == 0:
            f_len[i] = 1
            f_cnt[i] = 1
        else:
            f_len[i] = max_len + 1
            f_cnt[i] = cnt
        fenw_forward.update(comp_val, f_len[i], f_cnt[i])

    # Backward pass: we traverse from right to left in the original array.
    # We create an array of negative values in reverse order.
    rev_a = [-x for x in a][::-1]
    g_len_rev = [0] * n
    g_cnt_rev = [0] * n
    fenw_backward = Fenw(comp_size)
    for i in range(n):
        val = rev_a[i]
        comp_val = mapping[val]
        if comp_val > 1:
            max_len, cnt = fenw_backward.query(comp_val-1)
        else:
            max_len, cnt = (0,0)
        if max_len == 0:
            g_len_rev[i] = 1
            g_cnt_rev[i] = 1
        else:
            g_len_rev[i] = max_len + 1
            g_cnt_rev[i] = cnt
        fenw_backward.update(comp_val, g_len_rev[i], g_cnt_rev[i])

    # Reverse the arrays to get g_len and g_cnt for the original indices.
    g_len = g_len_rev[::-1]
    g_cnt = g_cnt_rev[::-1]

    L = max(f_len) if n>0 else 0
    total_count = 0
    for i in range(n):
        if f_len[i] == L:
            total_count += f_cnt[i]

    res = []
    for i in range(n):
        if f_len[i] + g_len[i] - 1 != L:
            res.append('1')
        else:
            if f_cnt[i] * g_cnt[i] == total_count:
                res.append('3')
            else:
                res.append('2')

    print(''.join(res))

