def create_board(N):
    if N == 1:
        return None

    # Create an empty board
    board = [[0] * N for _ in range(N)]

    # Place 1 in the center-ish position for flexibility
    center_row = N // 2
    center_col = N // 2
    board[center_row][center_col] = 1

    current_num = 2
    direction = 1  # 1 for forward, -1 for backward

    # Fill the board in a spiral pattern, alternating directions
    # to create interesting movement patterns
    for layer in range(max(N//2, 1)):
        # Top row
        for j in range(layer, N - layer):
            if board[layer][j] == 0:
                board[layer][j] = current_num
                current_num += 1

        # Right column
        for i in range(layer + 1, N - layer):
            if board[i][N - layer - 1] == 0:
                board[i][N - layer - 1] = current_num
                current_num += 1

        # Bottom row
        for j in range(N - layer - 2, layer - 1, -1):
            if board[N - layer - 1][j] == 0:
                board[N - layer - 1][j] = current_num
                current_num += 1

        # Left column
        for i in range(N - layer - 2, layer, -1):
            if board[i][layer] == 0:
                board[i][layer] = current_num
                current_num += 1

    # Ensure all cells are filled
    for i in range(N):
        for j in range(N):
            if board[i][j] == 0:
                board[i][j] = current_num
                current_num += 1

    return board

def main():
