def is_word_mentioned(text, word):
    """Check if a word is mentioned in text as a standalone word"""
    import re
    # Create regex pattern to match the word as a standalone word
    pattern = r'(^|[^a-zA-Z0-9])' + re.escape(word) + r'($|[^a-zA-Z0-9])'
    return bool(re.search(pattern, text))

def solve_chat(n, users, m, messages):
    # Parse messages into (sender, text) pairs
    parsed_msgs = []
    for msg in messages:
        parts = msg.split(':', 1)
        if len(parts) < 2:
            return None  # Invalid format
        sender, text = parts[0], parts[1]
        parsed_msgs.append((sender, text))

    # Check known messages for self-mention and consecutive same senders
    for i in range(m):
        sender, text = parsed_msgs[i]
        if sender != '?':
            # Check if known sender mentions themselves
            if is_word_mentioned(text, sender):
                return None

            # Check consecutive messages with same sender
            if i > 0 and parsed_msgs[i-1][0] != '?' and parsed_msgs[i-1][0] == sender:
                return None
            if i < m-1 and parsed_msgs[i+1][0] != '?' and parsed_msgs[i+1][0] == sender:
                return None

    # Backtracking to assign unknown senders
    def backtrack(idx):
        if idx == m:
            return True

        sender, text = parsed_msgs[idx]
        if sender != '?':
            # Already known sender, move to next
            return backtrack(idx + 1)

        # Try all possible senders for this unknown message
        for user in users:
            # Check if user mentions themselves
            if is_word_mentioned(text, user):
                continue

            # Check with previous message
            if idx > 0 and parsed_msgs[idx-1][0] != '?' and parsed_msgs[idx-1][0] == user:
                continue

            # Check with next message (if known)
            if idx < m-1 and parsed_msgs[idx+1][0] != '?' and parsed_msgs[idx+1][0] == user:
                continue

            # Assign and recurse
            parsed_msgs[idx] = (user, text)
            if backtrack(idx + 1):
                return True

        # Backtrack
        parsed_msgs[idx] = ('?', text)
        return False

    if backtrack(0):
        return parsed_msgs
    else:
        return None

def main():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        users = input().split()
        m = int(input().strip())
        messages = []
        for _ in range(m):
            messages.append(input().strip())

        result = solve_chat(n, users, m, messages)
        if result is None:
            print("Impossible")
        else:
            for sender, text in result:
                print(f"{sender}:{text}")

