MOD = 10**9 + 7

def main():
    n = int(input().strip())
    arr = list(map(int, input().split()))

    # Find free positions (0-indexed)
    free_positions = set()
    present_values = set()
    for i, val in enumerate(arr):
        if val == -1:
            free_positions.add(i)
        else:
            present_values.add(val)

    # All values from 1 to n
    all_values = set(range(1, n+1))
    free_values = all_values - present_values
    m = len(free_positions)

    # Count x: number of free positions i where value i+1 is also free
    x = 0
    for pos in free_positions:
        if (pos + 1) in free_values:
            x += 1

    # Precompute factorials and inverse factorials up to n
    fact = [1] * (n+1)
    inv_fact = [1] * (n+1)

    for i in range(1, n+1):
        fact[i] = fact[i-1] * i % MOD

    # Compute inverse factorials using Fermat's little theorem
    inv_fact[n] = pow(fact[n], MOD-2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    # Function to compute nCr
    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

    # Inclusion-exclusion: sum_{k=0}^x (-1)^k * C(x,k) * (m-k)!
    ans = 0
    for k in range(0, x+1):
        term = nCr(x, k) * fact[m - k] % MOD
        if k % 2 == 0:
            ans = (ans + term) % MOD
        else:
            ans = (ans - term) % MOD

    # Ensure positive modulo
    ans %= MOD
    if ans < 0:
        ans += MOD

    print(ans)

