def query(q_l, q_r, node=1, l=0, r=size-1, depth=0):
    if q_r < l or r < q_l:
        return 0
    if q_l <= l and r <= q_r:
        return tree[node]
    mid = (l + r) // 2
    lev = n - depth - 1
    if lev >= 0 and f[lev]:
        left_node = 2*node+1
        right_node = 2*node
    else:
        left_node = 2*node
        right_node = 2*node+1
    return query(q_l, q_r, left_node, l, mid, depth+1) + query(q_l, q_r, right_node, mid+1, r, depth+1)

