import collections

def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        print(-1)
        return

    n, m = map(int, data[0].split())
    matrix = []
    for i in range(1, 1+n):
        matrix.append(data[i].strip())

    total_nodes = n + m
    graph = [[] for _ in range(total_nodes)]

    # Build the graph without weights, but storing i and j for each edge.
    for i in range(n):
        for j in range(m):
            u = i
            v = n + j
            graph[u].append((v, i, j))
            graph[v].append((u, i, j))

    for c in [0,1]:
        visited = [False] * total_nodes
        values = [-1] * total_nodes
        consistent = True
        for start in range(total_nodes):
            if visited[start]:
                continue
            queue = collections.deque()
            queue.append(start)
            visited[start] = True
            values[start] = 0
            while queue:
                u = queue.popleft()
                for (v, i, j) in graph[u]:
                    orig_val = 1 if matrix[i][j] == '1' else 0
                    w = c ^ ( (i * j) % 2 ) ^ orig_val
                    expected = values[u] ^ w
                    if not visited[v]:
                        visited[v] = True
                        values[v] = expected
                        queue.append(v)
                    else:
                        if values[v] != expected:
                            consistent = False
                            break
                if not consistent:
                    break
            if not consistent:
                break

        if consistent:
            print(0)
            return

    print(-1)

