def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0])
    graph = []
    for i in range(1, 1 + n):
        graph.append(data[i].strip())

    # Precompute adjacency matrix as booleans
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if graph[i][j] == '1':
                adj[i][j] = True

    # DP state: dp[mask][last] = list of pattern counts for permutations ending with last
    # The list has length 2^(popcount(mask)-1)
    dp = [[None] * n for _ in range(1 << n)]

    # Initialize for single element permutations
    for i in range(n):
        mask = 1 << i
        # For single element, pattern length is 0, so we have 1 pattern (empty)
        dp[mask][i] = [1]

    # Iterate over all masks
    for mask in range(1 << n):
        size = bin(mask).count('1')
        if size < 1:
            continue

        for last in range(n):
            if not (mask & (1 << last)) or dp[mask][last] is None:
                continue

            current_patterns = dp[mask][last]
            pattern_length = size - 1

            for new_person in range(n):
                if mask & (1 << new_person):
                    continue

                new_mask = mask | (1 << new_person)
                edge_value = 1 if adj[last][new_person] else 0

                # Calculate new pattern: old_pattern * 2 + edge_value
                new_pattern_length = pattern_length + 1
                new_size = 1 << new_pattern_length

                if dp[new_mask][new_person] is None:
                    dp[new_mask][new_person] = [0] * new_size

                for pattern_val in range(len(current_patterns)):
                    if current_patterns[pattern_val] == 0:
                        continue
                    new_pattern_val = (pattern_val << 1) | edge_value
                    dp[new_mask][new_person][new_pattern_val] += current_patterns[pattern_val]

    # Collect results for full mask
    full_mask = (1 << n) - 1
    result = [0] * (1 << (n - 1))

    for last in range(n):
        if dp[full_mask][last] is not None:
            for pattern_val, count in enumerate(dp[full_mask][last]):
                result[pattern_val] += count

    # Output the results
    print(" ".join(map(str, result)))

