import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    index = 2

    parent = list(range(n+1))
    rank = [0] * (n+1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    diff = [0] * (n+2)

    for i in range(m):
        u = int(data[index]); v = int(data[index+1]); index += 2
        if u > v:
            u, v = v, u
        union(u, v)
        diff[u] += 1
        diff[v] -= 1

    cross = [0] * (n+1)
    s = 0
    for i in range(1, n+1):
        s += diff[i]
        cross[i] = s

    count = 0
    for i in range(1, n):
        if cross[i] > 0 and find(i) != find(i+1):
            union(i, i+1)
            count += 1

    print(count)

