import sys

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    index = 1
    output_lines = []
    for _ in range(t):
        # Skip empty lines if any
        while index < len(data) and data[index] == '':
            index += 1
        if index >= len(data):
            break
        m = int(data[index]); k = int(data[index+1]); index += 2
        a = [0] * (k+1)
        for i in range(1, k+1):
            a[i] = int(data[index]); index += 1
        events = []
        unknown_count = 0
        used = [0] * (k+1)
        for i in range(m-1):
            t_val = int(data[index]); r_val = int(data[index+1]); index += 2
            events.append((t_val, r_val))
            if t_val > 0:
                used[t_val] += 1
            else:
                unknown_count += 1

        first_disappointed = -1
        for i, (t_val, r_val) in enumerate(events):
            if r_val == 1 and first_disappointed == -1:
                first_disappointed = i

        if first_disappointed == -1:
            # No disappointed event
            s = []
            for i in range(1, k+1):
                if used[i] + unknown_count >= a[i]:
                    s.append('Y')
                else:
                    s.append('N')
            output_lines.append(''.join(s))
        else:
            # There is disappointed event
            known0 = [0] * (k+1)
            U0 = 0
            # Process events before first_disappointed
            for i in range(first_disappointed):
                t_val, r_val = events[i]
                if t_val > 0:
                    known0[t_val] += 1
                else:
                    U0 += 1

            # Compute S = sum_{j} max(0, a[j] - known0[j] - 1)
            S = 0
            for j in range(1, k+1):
                cap = a[j] - known0[j] - 1
                if cap > 0:
                    S += cap
                # else cap <=0, so add 0

            res = []
            for i in range(1, k+1):
                need = a[i] - known0[i]
                if need >= 0 and need <= U0:
                    # Compute capacity for other dishes without causing exhaustion (for dish i we assign need)
                    # For this dish i, the capacity without exhaustion would be max(0, a[i]-known0[i]-1) but we are using it fully.
                    # So the available capacity for other dishes is S - max(0, a[i]-known0[i]-1) 
                    other_cap = S - max(0, a[i]-known0[i]-1)
                    if other_cap >= U0 - need:
                        res.append('Y')
                    else:
                        if used[i] + unknown_count >= a[i]:
                            res.append('Y')
                        else:
                            res.append('N')
                else:
                    if used[i] + unknown_count >= a[i]:
                        res.append('Y')
                    else:
                        res.append('N')
            output_lines.append(''.join(res))

    print('\n'.join(output_lines))

