import heapq

def main():
    import sys
    data = sys.stdin.read().splitlines()
    n = int(data[0])
    parent = [0] * (n+1)
    c = [0] * (n+1)
    children = [set() for _ in range(n+1)]
    root = None

    for i in range(1, n+1):
        parts = data[i].split()
        p_val = int(parts[0])
        c_val = int(parts[1])
        if p_val == -1:
            root = i
            parent[i] = 0
        else:
            parent[i] = p_val
            children[p_val].add(i)
        c[i] = c_val

    badChildCount = [0] * (n+1)
    for i in range(1, n+1):
        for child in children[i]:
            if c[child] == 0:
                badChildCount[i] += 1

    heap = []
    for i in range(1, n+1):
        if i == root:
            continue
        if c[i] == 1 and badChildCount[i] == 0:
            heapq.heappush(heap, i)

    result = []
    while heap:
        v = heapq.heappop(heap)
        result.append(str(v))
        p = parent[v]
        if p == 0:
            continue

        # Move all children of v to p
        for u in list(children[v]):   # use list to avoid modification during iteration
            children[p].add(u)
            parent[u] = p
            if c[u] == 0:
                badChildCount[p] += 1
        children[v].clear()

        # Remove v from children of p
        children[p].discard(v)
        if c[v] == 0:
            badChildCount[p] -= 1

        # Check if p becomes deletable
        if p != root and c[p] == 1 and badChildCount[p] == 0:
            heapq.heappush(heap, p)

    if not result:
        print(-1)
    else:
        print(" ".join(result))

