import collections

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        print(0)
        return

    n = int(data[0])
    a_list = list(map(int, data[1:1+n]))
    edges = data[1+n:1+n+2*(n-1)]

    graph = [[] for _ in range(n+1)]
    for i in range(n-1):
        u = int(edges[2*i]); v = int(edges[2*i+1])
        graph[u].append(v)
        graph[v].append(u)

    MAX = 200000
    is_prime = [True] * (MAX+1)
    primes = []
    is_prime[0] = is_prime[1] = False
    for i in range(2, MAX+1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i*i, MAX+1, i):
                is_prime[j] = False

    vertex_primes = [[] for _ in range(n+1)]
    for i in range(1, n+1):
        num = a_list[i-1]
        temp = num
        for p in primes:
            if p * p > temp:
                break
            if temp % p == 0:
                vertex_primes[i].append(p)
                while temp % p == 0:
                    temp //= p
        if temp > 1 and temp <= MAX and is_prime[temp]:
            vertex_primes[i].append(temp)

    prime_to_vertices = {}
    for p in primes:
        prime_to_vertices[p] = []
    for i in range(1, n+1):
        for p in vertex_primes[i]:
            prime_to_vertices[p].append(i)

    ans = 0
    # We'll iterate only over primes that have at least one vertex
    for p in primes:
        S = set(prime_to_vertices[p])
        if not S:
            continue
        visited = set()
        for v in prime_to_vertices[p]:
            if v not in visited:
                comp = []
                stack = [v]
                visited.add(v)
                while stack:
                    u = stack.pop()
                    comp.append(u)
                    for neighbor in graph[u]:
                        if neighbor in S and neighbor not in visited:
                            visited.add(neighbor)
                            stack.append(neighbor)
                if not comp:
                    continue
                # First BFS to find the farthest node from comp[0]
                dist1 = {}
                queue = collections.deque([comp[0]])
                dist1[comp[0]] = 1
                farthest1 = comp[0]
                while queue:
                    u = queue.popleft()
                    if dist1[u] > dist1[farthest1]:
                        farthest1 = u
                    for neighbor in graph[u]:
                        if neighbor in comp and neighbor not in dist1:
                            dist1[neighbor] = dist1[u] + 1
                            queue.append(neighbor)

                # Second BFS from farthest1
                dist2 = {}
                queue = collections.deque([farthest1])
                dist2[farthest1] = 1
                farthest2 = farthest1
                while queue:
                    u = queue.popleft()
                    if dist2[u] > dist2[farthest2]:
                        farthest2 = u
                    for neighbor in graph[u]:
                        if neighbor in comp and neighbor not in dist2:
                            dist2[neighbor] = dist2[u] + 1
                            queue.append(neighbor)
                diameter = dist2[farthest2]
                if diameter > ans:
                    ans = diameter

    print(ans if ans > 0 else 0)

if __name__ == '__main__':
    main()

