import bisect

def main():
    import sys
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])
    points = list(map(int, data[2:2+n+m]))
    types = list(map(int, data[2+n+m:2+2*(n+m)]))

    drivers = []
    # Extract the driver coordinates
    for i in range(n+m):
        if types[i] == 1:
            drivers.append(points[i])

    ans = [0] * len(drivers)

    for i in range(n+m):
        if types[i] == 0:
            x = points[i]
            idx = bisect.bisect_left(drivers, x)
            left_idx = idx - 1
            right_idx = idx

            if left_idx < 0:
                ans[right_idx] += 1
            elif right_idx >= len(drivers):
                ans[left_idx] += 1
            else:
                left_dist = x - drivers[left_idx]
                right_dist = drivers[right_idx] - x
                if left_dist <= right_dist:
                    ans[left_idx] += 1
                else:
                    ans[right_idx] += 1

    print(" ".join(map(str, ans)))

if __name__ == "__main__":
    main()

MOD = 10**9+7
M = 1000000

import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Precompute Möbius function for [0, M]
    mu = [1] * (M+1)
    is_prime = [True] * (M+1)
    primes = []
    for i in range(2, M+1):
        if is_prime[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > M:
                break
            is_prime[i*p] = False
            if i % p == 0:
                mu[i*p] = 0
                break
            else:
                mu[i*p] = -mu[i]

    # Frequency array
    freq = [0] * (M+1)
    for x in a:
        if x <= M:
            freq[x] += 1

    # Precompute c[d] = count of multiples of d
    c = [0] * (M+1)
    for i in range(1, M+1):
        for j in range(i, M+1, i):
            c[i] += freq[j]

    # Precompute powers of 2 up to n
    max_power = n
    power2 = [1] * (max_power+1)
    for i in range(1, max_power+1):
        power2[i] = (power2[i-1] * 2) % MOD

    # Precompute T[d] = c[d] * 2^(c[d]-1) mod MOD
    T = [0] * (M+1)
    for d in range(1, M+1):
        if c[d] == 0:
            continue
        T[d] = c[d] * power2[c[d]-1] % MOD

    # Now compute the answer
    ans = 0
    for g in range(2, M+1):
        s = 0
        k = 1
        while k * g <= M:
            d = k * g
            s = (s + mu[k] * T[d]) % MOD
            k += 1
        s %= MOD
        if s < 0:
            s += MOD
        ans = (ans + g * s) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

