# Precompute the position of each value
pos = [0] * (n+1)
for idx, val in enumerate(p):
    pos[val] = idx

# Precompute left_bound: first index to the left that is greater
left_bound = [-1] * n
stack = []
for i in range(n):
    while stack and p[stack[-1]] < p[i]:
        stack.pop()
    if stack:
        left_bound[i] = stack[-1]
    else:
        left_bound[i] = -1
    stack.append(i)

# Precompute right_bound: first index to the right that is greater
right_bound = [n] * n
stack = []
for i in range(n-1, -1, -1):
    while stack and p[stack[-1]] < p[i]:
        stack.pop()
    if stack:
        right_bound[i] = stack[-1]
    else:
        right_bound[i] = n
    stack.append(i)

count = 0
