    M = p[i]
    L = left_bound[i] + 1
    R = right_bound[i] - 1
    left_size = i - L + 1
    right_size = R - i + 1
    if left_size <= right_size:
        # iterate over left part
        for l in range(L, i+1):
            target = M - p[l]
            if target < 1 or target > n:
                continue
            j = pos[target]
            if j >= i and j <= R:
                count += 1
    else:
        # iterate over right part
        for r in range(i, R+1):
            target = M - p[r]
            if target < 1 or target > n:
                continue
            j = pos[target]
            if j >= L and j <= i:
                count += 1

