import collections

def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        print(0)
        return

    n, m = map(int, data[0].split())
    edges = []
    for i in range(1, m+1):
        parts = data[i].split()
        u = int(parts[0])
        v = int(parts[1])
        c = parts[2]
        edges.append((u, v, c))

    def solve(T):
        graph = [[] for _ in range(n+1)]
        for (u, v, c) in edges:
            color_val = 1 if c == 'R' else 0
            w = color_val ^ T
            graph[u].append((v, w))
            graph[v].append((u, w))

        visited = [False] * (n+1)
        assignment = [0] * (n+1)
        total_moves = 0
        flipped_list = []

        for i in range(1, n+1):
            if not visited[i]:
                comp_nodes = []
                queue = collections.deque()
                queue.append(i)
                visited[i] = True
                assignment[i] = 0
                comp_nodes.append(i)
                consistent = True
                while queue:
                    u = queue.popleft()
                    for (v, w) in graph[u]:
                        expected = assignment[u] ^ w
                        if not visited[v]:
                            visited[v] = True
                            assignment[v] = expected
                            comp_nodes.append(v)
                            queue.append(v)
                        else:
                            if assignment[v] != expected:
                                consistent = False
                if not consistent:
                    return (False, 0, [])

                count_ones = sum(assignment[node] for node in comp_nodes)
                size = len(comp_nodes)
                if count_ones <= size - count_ones:
                    for node in comp_nodes:
                        if assignment[node] == 1:
                            flipped_list.append(node)
                            total_moves += 1
                else:
                    for node in comp_nodes:
                        if assignment[node] == 0:
                            flipped_list.append(node)
                            total_moves += 1

        return (True, total_moves, flipped_list)

    res0 = solve(0)
    res1 = solve(1)

    if not res0[0] and not res1[0]:
        print(-1)
    elif not res0[0]:
        print(res1[1])
        if res1[1] > 0:
            print(" ".join(map(str, res1[2])))
    elif not res1[0]:
        print(res0[1])
        if res0[1] > 0:
            print(" ".join(map(str, res0[2])))
    else:
        if res0[1] <= res1[1]:
            print(res0[1])
            if res0[1] > 0:
                print(" ".join(map(str, res0[2])))
        else:
            print(res1[1])
            if res1[1] > 0:
                print(" ".join(map(str, res1[2])))

if __name__ == '__main__':
    main()

